from pyspark.errors import StreamingQueryException


def hourly_counts(events):
    # Step 6: the watermark policy. Takes the event stream and returns window_start and events, per hour.
    return events


def run_hourly(stream, checkpoint, fail_at=None):
    """Run hourly_counts(stream) in append mode until every waiting file is read. Returns the query and the rows each
    micro-batch published, by micro-batch id. With fail_at, that micro-batch fails before it saves its rows (as if
    the sink went down), which stops the query."""
    published = {}

    def publish(batch_df, batch_id):
        rows = [tuple(r) for r in batch_df.collect()]
        if batch_id == fail_at:
            raise RuntimeError("the sink went down")
        published[batch_id] = rows

    q = (hourly_counts(stream).writeStream.outputMode("append").foreachBatch(publish)
         .option("checkpointLocation", checkpoint).trigger(availableNow=True).start())
    try:
        q.awaitTermination()
    except StreamingQueryException:
        pass
    return q, published


